'use strict';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>String(s||'N').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const state={me:null,csrf:'',page:'Overview',tab:'',people:[],projects:[],conversations:[],conversation:null,messages:[],reply:null,selectedMessage:null,poll:null,revision:0};
const canWrite=()=>state.me?.user.role!=='viewer';
const isRole=(...roles)=>roles.includes(state.me?.user.role);
const currency=cents=>new Intl.NumberFormat(undefined,{style:'currency',currency:state.me?.organization.currency||'USD'}).format((cents??0)/100);
const dt=value=>value?new Date(value).toLocaleString([],{dateStyle:'medium',timeStyle:'short'}):'—';
const badge=s=>`<span class="status ${escape(s)}">${escape(String(s).replaceAll('_',' '))}</span>`;
const button=(label,action,id='',primary=false)=>`<button aria-label="${escape(label.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim()||(action==='navigate'?'Open '+id:action.replaceAll('-',' ')))}" class="btn ${primary?'primary':''}" data-action="${action}" data-id="${escape(id)}">${label}</button>`;
const empty=(title,description,action='',label='Create first record')=>`<div class="card empty-state"><span class="spark">◇</span><h3>${title}</h3><p>${description}</p>${action&&canWrite()?button(label,action,'',true):''}</div>`;
const heading=(title,sub,actions='')=>`<div class="titlebar"><div><div class="eyebrow">YOUR CONNECTED WORKSPACE</div><h1>${escape(title)}</h1><div class="subtitle">${escape(sub)}</div></div><div class="actions">${actions}</div></div>`;
const table=(columns,rows)=>`<div class="card table-wrap"><table class="table"><thead><tr>${columns.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const cell=s=>`<td>${s}</td>`;
const field=(name,label,type='text',value='',opts={})=>{
  const input=`<input id="f-${name}" name="${name}" type="${type}" value="${escape(value)}" ${opts.required===false?'':'required'} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.minlength?`minlength="${opts.minlength}"`:''} ${opts.step?`step="${opts.step}"`:''} ${opts.maxlength?`maxlength="${opts.maxlength}"`:''} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''} ${opts.placeholder?`placeholder="${escape(opts.placeholder)}"`:''}>`;
  return `<div class="${opts.full?'full':''}"><label for="f-${name}">${label}</label>${type==='password'?`<div class="password-control">${input}<button type="button" data-action="toggle-password" data-id="f-${name}" aria-label="Show password" aria-pressed="false">${nexusIcon('eye')}</button></div>`:input}</div>`;
};
const area=(name,label,value='',required=false)=>`<div class="full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${required?'required':''}>${escape(value)}</textarea></div>`;
const select=(name,label,options,value='',required=true)=>`<div><label for="f-${name}">${label}</label><select name="${name}" id="f-${name}" ${required&&options[0]?.[0]!==''?'required':''}>${options.map(o=>`<option value="${escape(o[0])}" ${o[0]===value?'selected':''}>${escape(o[1])}</option>`).join('')}</select></div>`;
const projectOptions=()=>[['','Workspace-wide'],...state.projects.filter(p=>p.status!=='archived').map(p=>[p.id,p.name+(p.private?' · Private':'')])];
const peopleOptions=()=>state.people.map(p=>[p.id,p.name]);

async function api(path,method='GET',data){
  const options={method,headers:{'Accept':'application/json'},credentials:'same-origin'};
  if(method!=='GET'){options.headers['Content-Type']='application/json';if(state.csrf)options.headers['X-CSRF-Token']=state.csrf;options.body=JSON.stringify(data||{});}
  let response;
  try{response=await fetch('/api'+path,options);}catch{throw new Error('Cannot reach the server. Check that Nexus is running.');}
  const result=await response.json();
  if(!response.ok){if(response.status===401&&state.me){state.me=null;stopPolling();showAuth('login');}throw new Error(result.error||'The request could not be completed.');}
  return result;
}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function stopPolling(){clearInterval(state.poll);state.poll=null;}
function modal(title,body,form='',submit='Save',wide=false){
  const d=$('#modal');d.classList.remove('document-dialog');d.classList.toggle('wide',wide);
  d.innerHTML=`<h2>${escape(title)}</h2>${form?`<form data-form="${form}">${body}<div class="form-error" role="alert"></div><div class="actions">${button('Cancel','close-modal')}<button class="btn primary" type="submit">${submit}</button></div></form>`:body+`<div class="actions spacer-top">${button('Close','close-modal')}</div>`}`;
  d.querySelectorAll('button[data-action]').forEach(b=>b.type='button');
  if(!d.open)d.showModal();
}
function closeModal(){if(state.uploading){toast('Your upload is in progress. Please wait for it to finish.');return;}$('#modal').close();$('#modal').innerHTML='';}
function authFields(mode){return `${mode!=='login'?field('name','Your name','text','',{maxlength:160,autocomplete:'name'}):''}${mode==='register'?field('organization','Organization name','text','',{maxlength:160,autocomplete:'organization'}):''}${field('email','Email address','email','',{maxlength:254,autocomplete:'username',placeholder:'you@company.com'})}${field('password','Password','password','',{minlength:mode==='login'?undefined:12,maxlength:1024,autocomplete:mode==='login'?'current-password':'new-password',placeholder:mode==='login'?'Enter your password':'At least 12 characters'})}${mode==='register'?select('currency','Workspace currency',[['USD','USD — US dollar'],['ZAR','ZAR — South African rand'],['EUR','EUR — Euro'],['GBP','GBP — British pound']])+field('industry','Industry','text','General',{required:false,maxlength:100}):''}${mode==='join'?field('token','Invitation token','text','',{maxlength:128}):''}`;}
function showAuth(mode='login',token=''){
  stopPolling();$('#shell').hidden=true;$('#auth').hidden=false;
  $('#auth').innerHTML=`<div class="auth-layout"><section class="auth-hero"><div class="brand"><span class="mark">N</span>NEXUS</div><div class="auth-hero-content"><div class="auth-hero-eyebrow">YOUR CONNECTED BUSINESS WORKSPACE</div><h2>Everything your business needs.<br><span>In sync.</span></h2><p>Bring your people, projects, conversations and operations into one connected workspace.</p><div class="auth-apps">${[['briefcase','Projects'],['chat','Conversations'],['wallet','Finance'],['folder','Documents'],['users','Your team'],['spark','Intelligence']].map(a=>`<span>${nexusIcon(a[0])}${a[1]}</span>`).join('')}</div></div><div class="auth-proof">${nexusIcon('shield')} Connected records. Clear ownership. Decisions with context.</div></section><section class="auth-form-pane"><div class="auth-card"><div class="auth-intro">NEXUS WORKSPACE</div><h1>${mode==='register'?'Make room for better work.':mode==='join'?'Your team is waiting.':'Welcome back.'}</h1><p class="hint">${mode==='register'?'Create your organization and start connecting your business.':mode==='join'?'Accept your invitation to join your organization.':'Sign in to pick up where your team left off.'}</p><div class="auth-tabs"><button data-action="auth-mode" data-id="login" class="${mode==='login'?'selected':''}">Sign in</button><button data-action="auth-mode" data-id="register" class="${mode==='register'?'selected':''}">Create workspace</button><button data-action="auth-mode" data-id="join" class="${mode==='join'?'selected':''}">Join team</button></div><form data-form="auth" data-mode="${mode}">${authFields(mode)}<div class="form-error" role="alert"></div><button type="submit" class="btn primary">${mode==='register'?'Create workspace':mode==='join'?'Accept invitation':'Sign in to workspace'} ${nexusIcon('arrow')}</button></form><div class="auth-divider">LOOK AROUND FIRST</div><button type="button" class="demo-entry" data-action="auth-demo">${nexusIcon('layers')} Explore a seeded workspace ${nexusIcon('arrow')}</button><p class="auth-footnote">${nexusIcon('lock')} Demo data is kept in its own workspace.<br>Your business records are saved on this Nexus server.</p></div></section></div>`;
  if(token)$('#f-token').value=token;
}
const navs=[['◫','Overview'],['☷','Nexus Connect'],['▣','Projects'],['✓','Tasks'],['◎','Customers'],['▦','Operations'],['◇','Procurement'],['▤','Finance'],['⌑','Assets'],['▧','Contracts'],['▧','Documents'],['◷','Meetings'],['♧','People'],['⊞','Industry apps'],['↪','Automations'],['✧','Intelligence'],['▥','Audit log']];
function renderNav(){
  const styles={'Automations':['layers','teal'],'Overview':['overview','indigo'],'Nexus Connect':['chat','violet'],'Projects':['briefcase','blue'],'Tasks':['check','teal'],'Customers':['users','rose'],'Operations':['box','amber'],'Procurement':['cart','amber'],'Finance':['wallet','blue'],'Assets':['asset','teal'],'Contracts':['file','rose'],'Documents':['folder','amber'],'Meetings':['calendar','violet'],'People':['users','teal'],'Industry apps':['layers','blue'],'Intelligence':['spark','violet'],'Audit log':['shield','indigo']};
  $('#nav').innerHTML=navs.filter(n=>n[1]!=='Automations'||isRole('admin')).filter(n=>n[1]!=='Finance'||isRole('admin','finance')).filter(n=>n[1]!=='Contracts'||isRole('admin','manager','finance')).filter(n=>n[1]!=='Audit log'||isRole('admin')).map((n,i)=>`${i===0?'<div class="navlabel">WORKSPACE</div>':i===2?'<div class="navlabel">BUSINESS OPERATIONS</div>':n[1]==='Documents'?'<div class="navlabel">COLLABORATION</div>':n[1]==='Industry apps'?'<div class="navlabel">INTELLIGENCE & CONTROL</div>':''}<button aria-label="${n[1]}" title="${n[1]}" class="${state.page===n[1]?'active':''}" data-action="navigate" data-id="${n[1]}"><span class="nav-icon-shell tone-${styles[n[1]][1]}">${nexusIcon(styles[n[1]][0])}</span><span class="navtext">${n[1]}</span></button>`).join('');
}
async function enter(){
  state.me=await api('/me');state.csrf=state.me.csrf;
  $('#auth').hidden=true;$('#auth').innerHTML='';$('#shell').hidden=false;$('#workspaceNotice').hidden=!state.me.organization.is_demo;$('#workspaceNotice').innerHTML=state.me.organization.is_demo?`<span class="workspace-notice-left">${nexusIcon('layers')}<span><strong>Demo workspace</strong> · Sample data. Changes are saved here, separately from your business.</span></span><button class="btn" data-action="auth-mode" data-id="register">Create your workspace ${nexusIcon('arrow')}</button>`:'';
  const u=state.me.user,o=state.me.organization;
  $('#orgName').textContent=o.name;$('#orgRole').textContent=o.industry+' · '+o.currency;
  $('#orgInitials').textContent=initials(o.name);$('#userInitials').textContent=initials(u.name);$('#headerInitials').textContent=initials(u.name);$('#userName').textContent=u.name;$('#userRole').textContent=u.role;
  await refreshReference();await navigate('Overview');await updateNotifications();
}
async function refreshReference(){[state.people,state.projects,state.conversations]=await Promise.all([api('/people'),api('/projects'),api('/conversations')]);}
function navigate(page){
  state.nextPage=page;
  if(state.navigationPromise)return state.navigationPromise;
  state.navigationPromise=(async()=>{
    while(state.nextPage){
      const target=state.nextPage;state.nextPage=null;
      stopPolling();state.page=target;state.tab='';state.revision++;renderNav();$('#crumb').textContent=target;
      $('#app').innerHTML='<div class="loading">Loading workspace records…</div>';
      try{await render();window.scrollTo({top:0,behavior:'instant'});}catch(e){if(state.me)$('#app').innerHTML=heading(target,'')+`<div class="error">${escape(e.message)}</div>`;}
    }
  })().finally(()=>{state.navigationPromise=null;});
  return state.navigationPromise;
}
async function render(){
  const routes={'Automations':renderAutomations,'Overview':overview,'Projects':projects,'Tasks':tasks,'Nexus Connect':connect,'Customers':customers,'Operations':operations,'Procurement':procurement,'Finance':finance,'Assets':assets,'Contracts':contracts,'Documents':knowledge,'Meetings':meetings,'People':people,'Industry apps':industry,'Intelligence':intelligence,'Audit log':audit,'Settings':settings};
  await (routes[state.page]||overview)();
}
function footer(){return `<div class="footer"><span>${nexusIcon('building')} ${escape(state.me.organization.name)} · ${state.me.organization.is_demo?'Sample workspace':'Connected workspace'}</span><span>${nexusIcon('shield')} ${escape(state.me.user.role)} access</span></div>`;}
function projectRows(ps,ts=[]){return ps.map(p=>{const tasks=ts.filter(t=>t.project_id===p.id),done=tasks.filter(t=>t.status==='done').length,progress=tasks.length?Math.round(done/tasks.length*100):0;return `<tr>${cell(`<button class="link" data-action="project-detail" data-id="${p.id}">${escape(p.name)} ${p.private?'🔒':''}</button><span class="subtext">${escape(p.owner_name||'')}</span>`)}${cell(badge(p.status))}${cell(`${progress}% · ${done}/${tasks.length} tasks`)}${cell(currency(p.budget))}</tr>`;});}
async function overview(){await renderExecutiveOverview();}
async function projects(){
  const [ps,ts]=await Promise.all([api('/projects'),api('/tasks')]);state.projects=ps;
  $('#app').innerHTML=heading('Projects','A connected home for every piece of work.',canWrite()?button('＋ New project','new-project','',true):'')+(ps.length?table(['PROJECT','STATUS','PROGRESS','BUDGET'],projectRows(ps,ts)):empty('Bring your first project to life','Create a project and its contextual conversation is created automatically.','new-project'))+footer();
}
function newProject(){modal('Create a project',`<div class="form-grid">${field('name','Project name','text','',{maxlength:160,full:true})}${field('budget',`Budget (${state.me.organization.currency})`,'number','0',{min:0,step:'0.01'})}${field('due_date','Due date','date','',{required:false})}${area('description','Description')}<div class="full"><label class="label-inline"><input type="checkbox" name="private"> Private project — only assigned members and administrators</label></div></div>`,'project','Create project');}
async function projectDetail(id){
  const p=state.projects.find(x=>x.id===id)|| (await api('/projects')).find(x=>x.id===id);if(!p)throw new Error('Project unavailable');
  const members=await api(`/projects/${id}/members`);state.editProject=p;
  const manage=isRole('admin')||p.owner_id===state.me.user.user_id;
  modal(p.name,`<span class="pill ${p.private?'purple':'green'}">${p.private?'Private project':'Workspace project'}</span><p class="preformatted">${escape(p.description||'No description yet.')}</p><p class="hint">Budget: ${currency(p.budget)} · Due: ${escape(p.due_date||'Not set')} · Owner: ${escape(p.owner_name||'')}</p><div class="actions">${button('Open conversation','project-chat',id)}${canWrite()?button('Create task','project-task',id):''}</div><h3 class="inline-title spacer-top">Project status</h3>${manage?`<select class="select-small" data-change="project-status" data-id="${id}">${['active','at_risk','complete','archived'].map(s=>`<option ${s===p.status?'selected':''} value="${s}">${s.replace('_',' ')}</option>`).join('')}</select>`:badge(p.status)}<h3 class="inline-title spacer-top">Project members</h3>${members.map(m=>`<div class="member-list"><span class="avatar">${initials(m.name)}</span><span>${escape(m.name)}</span>${manage&&m.id!==p.owner_id?button('Remove access','remove-project-member',m.id):''}</div>`).join('')}${manage?`<div class="flex spacer-top"><select class="select-small grow" id="addProjectMember">${state.people.filter(u=>!members.some(m=>m.id===u.id)).map(u=>`<option value="${u.id}">${escape(u.name)}</option>`).join('')}</select>${button('Add member','add-project-member',id)}</div>`:''}`);
}
async function tasks(){const ts=await api('/tasks');state.tasks=ts;$('#app').innerHTML=heading('Tasks','Clear owners. Clear next steps.',canWrite()?button('＋ Create task','new-task','',true):'')+(ts.length?table(['TASK','ASSIGNEE','PROJECT','DUE','STATUS'],ts.map(t=>`<tr>${cell(escape(t.title)+(t.source_message_id?`<span class="subtext"><button class="text-button" data-action="source-message" data-id="${t.source_message_id}">From conversation ↗</button></span>`:''))}${cell(escape(t.assignee_name))}${cell(escape(t.project_name||'Workspace'))}${cell(escape(t.due_date||'—'))}${cell(canWrite()?`<select class="select-small" data-change="task-status" data-id="${t.id}">${['todo','doing','done'].map(s=>`<option value="${s}" ${s===t.status?'selected':''}>${s}</option>`).join('')}</select>`:badge(t.status))}</tr>`)):empty('Turn your next step into a task','Create tasks here or directly from a conversation.','new-task'))+footer();}
function newTask(source=null,project=''){
  state.taskSource=source;
  modal('Create a task',`<div class="form-grid">${field('title','Task name','text',source?.body?.slice(0,200)||'',{full:true,maxlength:200})}${select('assignee_id','Assignee',peopleOptions(),state.me.user.user_id)}${select('project_id','Project',projectOptions(),source?.project_id||project)}${field('due_date','Due date','date','',{required:false})}${select('priority','Priority',[['normal','Normal'],['high','High'],['low','Low']])}${area('description','Description',source?.body||'')}</div>${source?'<p class="hint">The task will retain a link to its source message.</p>':''}`,'task','Create task');
}
async function connect(){
  state.conversations=await api('/conversations');
  state.conversation=state.conversations.find(c=>c.id===state.conversation?.id)||state.conversations[0]||null;
  const c=state.conversation;
  if(state.aroundMessage&&state.aroundConversation!==c?.id)state.aroundMessage=null;
  $('#app').innerHTML=heading('Nexus Connect','Conversations with context. Decisions that become work.',button('✧ Assistant','assistant')+(canWrite()?button('＋ New conversation','new-conversation','',true):''))+`<section class="card connect"><div class="channels"><div class="channel-header"><span class="eyebrow">CONVERSATIONS</span></div><div class="channel-buttons">${state.conversations.map(v=>`<button class="${v.id===c?.id?'active':''} conversation-name" title="${escape(v.name)}" data-action="select-channel" data-id="${v.id}">${v.kind==='direct'?'◌':'#'} ${escape(v.name)} ${v.unread?`<span class="badge">${v.unread}</span>`:''}</button>`).join('')}</div><div class="channel-members"><b>TEAM PRESENCE</b><br>${state.people.map(p=>`${p.last_seen&&Date.now()/1000-p.last_seen<90?'🟢':'◌'} ${escape(p.name)}`).join('<br>')}</div></div><div class="chatbody">${c?`<div class="chathead"><div class="grow"><b>${c.kind==='direct'?'◌':'#'} ${escape(c.name)}</b><div class="subtitle">${c.project_id?`<button class="text-button" data-action="project-detail" data-id="${c.project_id}">Project record ↗</button>`:c.context_kind?button('Linked '+c.context_kind.replace('_',' ')+' record ↗','open-context',c.context_kind+':'+c.context_id):c.kind==='direct'?'Private conversation · Participants only':'Workspace channel'}</div></div><input class="chat-search" id="chatSearch" placeholder="Search messages…" aria-label="Search messages"></div><div class="messages" id="messageList"><div class="loading">Loading messages…</div></div>${canWrite()?`<div id="replyContext" class="reply-context" hidden></div><form class="composer" data-form="message"><textarea name="body" id="messageBody" aria-label="Message" placeholder="Message ${escape(c.name)}…" required maxlength="10000"></textarea><button class="btn primary" type="submit">Send ↑</button></form><div class="compose-controls"><label>Attach file (up to 5 MB) <input type="file" id="messageFile" aria-label="Attach a file"></label><span>Mentions: @email · Enter to send, Shift+Enter for a new line</span></div>`:'<div class="hint">Your viewer role has read-only access.</div>'}<div class="connection-state spacer-top" id="connectionState">Messages saved on server · Refreshes every 5 seconds</div>`:'<div class="empty">Create a conversation to get started.</div>'}</div></section>`;
  if(c){await loadMessages(true);stopPolling();state.poll=setInterval(()=>{if(state.page==='Nexus Connect'&&!document.hidden)loadMessages(false).catch(e=>{$('#connectionState').textContent=e.message;});},5000);}
}
async function loadMessages(scroll=false){
  const id=state.conversation?.id;if(!id)return;const query=$('#chatSearch')?.value||'';
  const rows=await api(`/conversations/${id}/messages${state.aroundMessage?'?around='+state.aroundMessage:query?'?q='+encodeURIComponent(query):''}`);
  if(state.page!=='Nexus Connect'||state.conversation?.id!==id)return;
  const list=$('#messageList');if(!list)return;
  const nearBottom=list.scrollHeight-list.scrollTop-list.clientHeight<80;
  const signature=JSON.stringify(rows);
  if(signature!==state.messageSignature||scroll){state.messages=rows;state.messageSignature=signature;list.innerHTML=rows.length?rows.map(messageHTML).join(''):'<div class="empty">Start the conversation. Messages and actions stay linked here.</div>';if(scroll||nearBottom)list.scrollTop=list.scrollHeight;}
  if(state.selectedMessage){const el=document.getElementById('m-'+state.selectedMessage);if(el){el.scrollIntoView({block:'center'});state.selectedMessage=null;}}
  $('#connectionState').textContent=`Messages saved on server · Last refreshed ${new Date().toLocaleTimeString()}`;
  if(rows.length)await api(`/conversations/${id}/read`,'POST',{through_id:rows[rows.length-1].id});
}
function messageHTML(m){
  const mine=m.author_id===state.me.user.user_id;
  return `<div class="message ${m.parent_id?'reply':''} ${m.deleted_at?'deleted':''}" id="m-${m.id}"><span class="avatar ${mine?'green':''}">${initials(m.author_name)}</span><div class="message-content">${m.pinned?'<div class="pinned-label">⌖ Pinned message</div>':''}${m.parent_id?'<div class="reply-context">↳ Reply in this conversation</div>':''}<b>${escape(m.author_name)}</b><small>${escape(dt(m.created_at))}${m.edited_at&&!m.deleted_at?' · edited':''}</small><p>${m.deleted_at?'Message removed · original retained in server history':escape(m.body)}</p>${m.attachments.map(a=>`<a class="attachment" href="/api/attachments/${a.id}">▧ ${escape(a.filename)} · ${(a.size/1024).toFixed(1)} KB ↓</a>`).join('')}${!m.deleted_at&&canWrite()?`<div class="message-toolbar"><button data-action="reply" data-id="${m.id}">↳ Reply</button><button data-action="react" data-id="${m.id}">👍</button><button data-action="message-task" data-id="${m.id}">＋ Task</button><button data-action="message-req" data-id="${m.id}">◇ Requisition</button>${isRole('admin','manager')?`<button data-action="pin-message" data-id="${m.id}">${m.pinned?'Unpin':'Pin'}</button>`:''}${mine?`<button data-action="edit-message" data-id="${m.id}">Edit</button><button data-action="remove-message" data-id="${m.id}">Remove</button>`:''}</div>`:''}${m.reactions.length?`<div class="reactions">${m.reactions.map(r=>`<button class="btn ${r.mine?'selected':''}" data-action="react" data-id="${m.id}" data-emoji="${escape(r.emoji)}">${escape(r.emoji)} ${r.count}</button>`).join('')}</div>`:''}${mine&&m.read_by.length?`<span class="read-receipt">Read by ${escape(m.read_by.map(r=>r.name).join(', '))}</span>`:''}</div></div>`;
}
function newConversation(){modal('New conversation',`<div class="form-grid">${field('name','Conversation name','text','',{full:true,maxlength:160})}${select('kind','Conversation type',[['channel','Workspace channel'],['direct','Private direct message']])}${select('member_id','Direct message participant',[['','Choose a team member'],...peopleOptions().filter(p=>p[0]!==state.me.user.user_id)],'',false)}</div><p class="hint">Channels are visible to the workspace. Direct messages are restricted to their two participants. Create a project to get a conversation governed by project access.</p>`,'conversation','Create conversation');}
async function sourceMessage(id){const m=await api('/messages/'+id);state.conversation=(await api('/conversations')).find(c=>c.id===m.conversation_id);state.selectedMessage=id;state.aroundMessage=id;state.aroundConversation=m.conversation_id;await navigate('Nexus Connect');toast('Showing the source message and surrounding conversation. Select a channel to return to recent messages.');}
async function customers(){const rows=await api('/customers');state.customers=rows;$('#app').innerHTML=heading('Customers','Manage relationships from first contact to customer.',canWrite()?button('＋ Add customer','new-customer','',true):'')+(rows.length?table(['NAME','COMPANY','EMAIL','PHONE','STAGE'],rows.map(r=>`<tr>${cell(escape(r.name)+`<span class="subtext">${button('Discuss record','record-chat','customer:'+r.id)}</span>`)}${cell(escape(r.company||'—'))}${cell(escape(r.email||'—'))}${cell(escape(r.phone||'—'))}${cell(canWrite()?`<select class="select-small" data-change="customer-stage" data-id="${r.id}">${['lead','qualified','customer','inactive'].map(s=>`<option ${s===r.stage?'selected':''}>${s}</option>`).join('')}</select>`:badge(r.stage))}</tr>`)):empty('Build your customer directory','Keep contacts and relationship stages in one shared place.','new-customer'))+footer();}
function newCustomer(){modal('Add a customer',`<div class="form-grid">${field('name','Contact or customer name','text','',{maxlength:160,full:true})}${field('company','Company','text','',{required:false,maxlength:160})}${field('email','Email','email','',{required:false,maxlength:254})}${field('phone','Phone','tel','',{required:false,maxlength:80})}${select('stage','Relationship stage',['lead','qualified','customer','inactive'].map(s=>[s,s]))}${area('notes','Notes')}</div>`,'customer','Add customer');}
async function operations(){
  const tab=state.tab||'Products';state.tab=tab;const [products,suppliers]=await Promise.all([api('/products'),api('/suppliers')]);state.products=products;state.suppliers=suppliers;
  const tabs=`<div class="module-tabs">${['Products','Suppliers','Purchase orders'].map(t=>`<button class="${tab===t?'selected':''}" data-action="tab" data-id="${t}">${t}</button>`).join('')}</div>`;
  let content;
  if(tab==='Products')content=products.length?table(['PRODUCT','SKU','UNIT PRICE','ON HAND','ACTIONS'],products.map(p=>`<tr>${cell(escape(p.name))}${cell(escape(p.sku))}${cell(currency(p.unit_price))}${cell(`${p.stock} ${escape(p.unit)}`)}${cell(isRole('admin','manager')?button('Adjust stock','stock',p.id):'—')}</tr>`)):empty('Your product and inventory catalog','Create products, then record stock movements with a reason.','new-product');
  else if(tab==='Suppliers')content=suppliers.length?table(['SUPPLIER','EMAIL','NOTES'],suppliers.map(s=>`<tr>${cell(escape(s.name)+`<span class="subtext">${button('Discuss record','record-chat','supplier:'+s.id)}</span>`)}${cell(escape(s.email||'—'))}${cell(escape(s.notes))}</tr>`)):empty('Connect your supplier directory','Suppliers become the counterparties on approved purchase orders.',isRole('admin','manager','finance')?'new-supplier':'');
  else if(isRole('admin','manager','finance')){const orders=await api('/purchase-orders');state.purchaseOrders=orders;content=orders.length?table(['ORDER','SUPPLIER','ITEM','TOTAL','STATUS'],orders.map(o=>`<tr>${cell(o.id.slice(0,8).toUpperCase())}${cell(escape(o.supplier_name))}${cell(`${o.quantity} × ${escape(o.item)}`)}${cell(currency(o.total))}${cell(badge(o.status))}</tr>`)):empty('No purchase orders yet','An approved, priced requisition and a supplier are required before an order can be issued.');}
  else content=empty('Restricted to procurement and finance','Your role cannot access purchase orders.');
  $('#app').innerHTML=heading('Operations','Products, inventory and suppliers in one place.',tab==='Products'&&isRole('admin','manager')?button('＋ Add product','new-product','',true):tab==='Suppliers'&&isRole('admin','manager','finance')?button('＋ Add supplier','new-supplier','',true):'')+tabs+content+footer();
}
function newProduct(){modal('Add a product',`<div class="form-grid">${field('name','Product name','text','',{full:true,maxlength:160})}${field('sku','Unique SKU','text','',{maxlength:80})}${field('unit','Unit','text','each',{maxlength:40})}${field('unit_price',`Unit price (${state.me.organization.currency})`,'number','0',{min:0,step:'0.01'})}</div><p class="hint">Opening stock starts at zero. Record a stock adjustment after creation.</p>`,'product','Create product');}
function newSupplier(){modal('Add a supplier',`<div class="form-grid">${field('name','Supplier name','text','',{full:true,maxlength:160})}${field('email','Email','email','',{required:false,maxlength:254})}${area('notes','Notes')}</div>`,'supplier','Add supplier');}
function stock(id){const p=state.products.find(p=>p.id===id);state.stockProduct=id;modal('Record stock movement',`<p class="hint">${escape(p.name)} · Currently ${p.stock} ${escape(p.unit)}</p><div class="form-grid">${field('quantity','Quantity change (negative for stock out)','number','1',{step:'1'})}${field('reason','Reason','text','',{maxlength:500})}</div>`,'stock','Save movement');}
async function procurement(){
  const rows=await api('/requisitions');state.requisitions=rows;
  $('#app').innerHTML=heading('Procurement','From a reviewed request to an authorized purchase.',canWrite()?button('＋ New requisition','new-req','',true):'')+`<div class="notice">Draft → Submit → Independent review → Purchase order. Requesters cannot approve their own requisitions. Purchase orders are recorded here; Nexus does not send orders or payments to suppliers.</div>`+(rows.length?table(['REQUEST','REQUESTER','PROJECT','ESTIMATED TOTAL','STATUS','ACTION'],rows.map(r=>`<tr>${cell(escape(r.item)+`<span class="subtext">${r.quantity} units</span>`)}${cell(escape(r.requester_name))}${cell(escape(r.project_name||'Workspace'))}${cell(currency(r.quantity*r.unit_price))}${cell(badge(r.status))}${cell(button('Open','req-detail',r.id))}</tr>`)):empty('Create a purchase request','Draft a requisition here or extract one from a project conversation.','new-req'))+footer();
}
function reqForm(r={}){return `<div class="form-grid">${field('item','Requested item','text',r.item||'',{maxlength:200,full:true})}${field('quantity','Quantity','number',r.quantity||1,{min:1,step:'1'})}${field('unit_price',`Estimated unit price (${state.me.organization.currency})`,'number',(r.unit_price||0)/100,{min:0,step:'0.01'})}${r.id?'':select('project_id','Project',projectOptions(),r.project_id||'')}${area('notes','Notes',r.notes||'')}</div>`;}
function newReq(draft=null){state.reqSource=draft;state.editReq=null;modal('Draft purchase requisition',`${draft?'<div class="notice">Fields extracted using a text rule. Review the item, quantity and price before saving. This does not issue a purchase order.</div>':''}${reqForm(draft||{})}`,'requisition','Save draft');}
async function reqDetail(id){
  const r=(await api('/requisitions')).find(r=>r.id===id);if(!r)throw new Error('Requisition unavailable');state.activeReq=r;
  const own=r.created_by===state.me.user.user_id;
  let actions='';
  if(canWrite()&&own&&['draft','rejected'].includes(r.status))actions+=button('Edit draft','edit-req',id)+button('Submit for review','submit-req',id,true);
  if(isRole('admin','manager')&&!own&&r.status==='submitted')actions+=button('Approve','review-approve',id,true)+button('Reject','review-reject',id);
  if(isRole('admin','manager')&&r.status==='approved')actions+=button('Issue purchase order','issue-order',id,true);
  modal('Purchase requisition',`${badge(r.status)}<h3>${escape(r.item)}</h3><p class="hint">${r.quantity} units × ${currency(r.unit_price)} = <b>${currency(r.quantity*r.unit_price)}</b><br>Requester: ${escape(r.requester_name)}<br>Project: ${escape(r.project_name||'Workspace')}<br>Created: ${dt(r.created_at)}</p><p class="preformatted">${escape(r.notes)}</p>${button('Discuss request','record-chat','requisition:'+r.id)}${r.source_message_id?button('Open source conversation','source-message',r.source_message_id):''}<h3 class="inline-title spacer-top">Decision history</h3>${r.approvals.length?r.approvals.map(a=>`<div class="review-history">${badge(a.decision)} ${escape(a.reviewer_name)} · ${dt(a.created_at)}<br>${escape(a.comment)}</div>`).join(''):'<p class="hint">No decisions recorded.</p>'}<div class="actions spacer-top">${actions}</div>${own&&r.status==='submitted'?'<p class="hint">An administrator or manager other than you must review this request.</p>':''}`);
}
async function reviewReq(id,decision){state.review={id,decision};modal(decision==='approved'?'Approve requisition':'Reject requisition',`<p class="hint">Your decision and identity will be recorded in the audit log.</p><div class="form-grid">${area('comment',decision==='rejected'?'Reason (required)':'Review comment','',decision==='rejected')}</div>`,'review',decision==='approved'?'Approve request':'Reject request');}
async function orderForm(id){const suppliers=await api('/suppliers');if(!suppliers.length)throw new Error('Create a supplier in Operations before issuing an order.');state.orderReq=id;modal('Issue purchase order',`<div class="notice">This records an issued order for the approved requisition. It does not contact the supplier or transfer funds.</div><div class="form-grid">${select('supplier_id','Supplier',suppliers.map(s=>[s.id,s.name]))}</div>`,'order','Issue order');}
async function finance(){
  const invoices=await api('/invoices');state.invoices=invoices;const ledger=await api('/ledger');state.ledger=ledger;
  const tab=state.tab||'Invoices';state.tab=tab;
  const tabs=`<div class="module-tabs">${['Invoices','General ledger'].map(t=>`<button class="${tab===t?'selected':''}" data-action="tab" data-id="${t}">${t}</button>`).join('')}</div>`;
  let content;
  if(tab==='Invoices')content=invoices.length?table(['INVOICE','CUSTOMER','AMOUNT','DUE','STATUS','ACTION'],invoices.map(i=>`<tr>${cell(escape(i.number)+`<span class="subtext">${button('Discuss invoice','record-chat','invoice:'+i.id)}</span>`)}${cell(escape(i.customer_name))}${cell(currency(i.total))}${cell(escape(i.due_date||'—'))}${cell(badge(i.status))}${cell(`<div class="row-actions">${i.status==='draft'?button('Issue','invoice-issue',i.id):i.status==='issued'?button('Record payment','invoice-payment',i.id)+button('Void','invoice-void',i.id):'—'}</div>`)}</tr>`)):empty('Create your first invoice','Drafts do not affect the ledger. Issuing an invoice posts receivables and revenue.','new-invoice');
  else content=`<div class="accounts">${['1000 Cash','1100 Accounts receivable','4000 Revenue'].map(a=>{const b=ledger.balances.find(b=>b.account===a);const v=b?(a==='4000 Revenue'?-b.balance:b.balance):0;return `<div class="card metric"><label>${a}</label><strong>${currency(v)}</strong><small>${a==='4000 Revenue'?'Credit balance':'Debit balance'}</small></div>`;}).join('')}</div>`+(ledger.lines.length?table(['POSTED','REFERENCE','ACCOUNT','DEBIT','CREDIT'],ledger.lines.map(l=>`<tr>${cell(dt(l.created_at))}${cell(escape(l.description))}${cell(escape(l.account))}${cell(l.debit?currency(l.debit):'—')}${cell(l.credit?currency(l.credit):'—')}</tr>`)):empty('The ledger has no postings','Issue an invoice to create its first balanced journal entry.'));
  $('#app').innerHTML=heading('Finance','Invoices and immutable, balanced accounting entries.',tab==='Invoices'?button('＋ Draft invoice','new-invoice','',true):button('Export journal','export-ledger'))+`<div class="notice">Single-currency, tax-exclusive invoicing. Payments are manual records of money received; no bank transfer is initiated. Tax, payroll, statutory reporting and bank reconciliation are outside this release.</div>`+tabs+content+footer();
}
async function newInvoice(){const cs=await api('/customers');if(!cs.length)throw new Error('Add a customer before creating an invoice.');modal('Draft invoice',`<div class="form-grid">${field('number','Unique invoice number','text','INV-'+new Date().getFullYear()+'-',{maxlength:80})}${select('customer_id','Customer',cs.map(c=>[c.id,c.name]))}${field('total',`Total (${state.me.organization.currency}, excluding tax)`,'number','',{min:'0.01',step:'0.01'})}${field('due_date','Due date','date','',{required:false})}${area('description','Description','',true)}</div>`,'invoice','Save invoice draft');}
async function invoiceAction(id,action){state.invoiceAction={id,action};const inv=state.invoices.find(i=>i.id===id);modal(action==='issue'?'Issue invoice':action==='payment'?'Record received payment':'Void issued invoice',`<p class="preformatted">${escape(inv.number)} · ${escape(inv.customer_name)}<br>Total: ${currency(inv.total)}</p><div class="notice">${action==='issue'?'This posts a debit to Accounts receivable and a credit to Revenue.':action==='payment'?'Confirm the full amount has actually been received. This posts a debit to Cash and a credit to Accounts receivable. No money is transferred.':'This posts a reversing journal entry. The original posting remains in the ledger.'}</div>`,'invoice-action',action==='payment'?'Record full payment':action==='issue'?'Issue and post':'Void and reverse');}
async function knowledge(){await renderDocumentLibrary();}
function newDoc(doc=null){state.editDoc=doc;modal(doc?'Edit document':'Create document',`<div class="form-grid">${field('title','Document title','text',doc?.title||'',{full:true,maxlength:200})}${!doc?select('project_id','Access context',projectOptions()):''}${area('body','Document content',doc?.body||'',true)}</div>`,'document',doc?'Save changes':'Create document');}
async function docDetail(id){await openDocument(id);}
async function meetings(){const ms=await api('/meetings');state.meetings=ms;$('#app').innerHTML=heading('Meetings','Schedule time, invite colleagues and keep meeting notes.',canWrite()?button('＋ Schedule meeting','new-meeting','',true):'')+(ms.length?table(['MEETING','START','END','ATTENDEES','YOUR RSVP'],ms.map(m=>{const mine=m.attendees.find(a=>a.user_id===state.me.user.user_id);return `<tr>${cell(`<button class="link" data-action="meeting-detail" data-id="${m.id}">${escape(m.title)}</button>`)}${cell(dt(m.starts_at))}${cell(dt(m.ends_at))}${cell(m.attendees.length)}${cell(mine?`<select class="select-small" data-change="rsvp" data-id="${m.id}">${['pending','accepted','declined'].map(s=>`<option ${s===mine.rsvp?'selected':''} ${s==='pending'?'disabled':''}>${s}</option>`).join('')}</select>`:'Not invited')}</tr>`;})):empty('Get the right people together','Meeting invitations appear in each attendee’s workspace notifications.','new-meeting'))+footer();}
function newMeeting(){modal('Schedule a meeting',`<div class="form-grid">${field('title','Meeting title','text','',{maxlength:200,full:true})}${field('starts_at','Starts (your local time)','datetime-local')}${field('ends_at','Ends (your local time)','datetime-local')}${select('project_id','Project',projectOptions())}<div class="full"><label>Invite attendees</label><div class="checkbox-row">${state.people.filter(p=>p.id!==state.me.user.user_id).map(p=>`<label><input type="checkbox" name="attendees" value="${p.id}">${escape(p.name)}</label>`).join('')||'<span class="hint">Invite teammates from People first.</span>'}</div></div>${area('notes','Agenda / meeting notes')}</div><p class="hint">Invitations are delivered inside Nexus. Audio/video and email delivery are not connected.</p>`,'meeting','Schedule meeting');}
function meetingDetail(id){const m=state.meetings.find(m=>m.id===id);modal(m.title,`<p class="hint">${dt(m.starts_at)} → ${dt(m.ends_at)}</p><div class="preformatted">${escape(m.notes||'No notes yet.')}</div><h3 class="inline-title spacer-top">Attendees</h3>${m.attendees.map(a=>`<div class="member-list"><span class="avatar">${initials(a.name)}</span>${escape(a.name)} ${badge(a.rsvp)}</div>`).join('')}`);}
async function people(){state.people=await api('/people');$('#app').innerHTML=heading('People','One connected workspace for your organization.',isRole('admin')?button('＋ Invite member','invite','',true):'')+table(['NAME','EMAIL','DEPARTMENT','ROLE','PRESENCE'],state.people.map(p=>`<tr>${cell(`<div class="flex"><span class="avatar purple">${initials(p.name)}</span>${escape(p.name)}</div>`)}${cell(escape(p.email))}${cell(escape(p.department||'—'))}${cell(isRole('admin')?`<button class="text-button" data-action="edit-role" data-id="${p.id}">${escape(p.role)} · Edit</button>`:escape(p.role))}${cell(p.last_seen&&Date.now()/1000-p.last_seen<90?'<span class="good">● Online</span>':'Away')}</tr>`))+`<p class="page-note">Administrators manage workspace roles. Private project membership is managed separately on the project record. Direct conversations are accessible only to their participants.</p>`+footer();}
function invite(){modal('Invite a teammate',`<div class="form-grid">${field('email','Team member email','email','',{full:true,maxlength:254})}${select('role','Workspace role',['member','manager','finance','viewer','admin'].map(s=>[s,s]))}${field('department','Department','text','',{required:false,maxlength:100})}</div><p class="hint">Nexus creates a single-use invitation valid for 24 hours. You share the invitation with your teammate; no email is sent automatically.</p>`,'invite','Create invitation');}
function editRole(id){const p=state.people.find(p=>p.id===id);state.editPerson=p;modal('Update team access',`<p class="hint">${escape(p.name)} · ${escape(p.email)}</p><div class="form-grid">${select('role','Role',['member','manager','finance','viewer','admin'].map(s=>[s,s]),p.role)}${field('department','Department','text',p.department,{required:false,maxlength:100})}</div><p class="hint">Role changes apply to the next request, including existing sessions.</p>`,'role','Update access');}
async function intelligence(){const d=await api('/dashboard'),overdue=d.tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<new Date().toLocaleDateString('en-CA')),risks=d.projects.filter(p=>p.status==='at_risk'),pending=d.requisitions.filter(r=>r.status==='submitted');$('#app').innerHTML=heading('Business intelligence','Operational signals computed from your actual workspace.')+`<div class="notice">These signals use deterministic rules over records you may access. Message extraction uses a text parser. A generative AI provider is not configured, and Nexus does not present generated answers as facts.</div><div class="modules">${[['Overdue tasks',overdue.length,'Open tasks whose due date has passed.','Tasks'],['Projects at risk',risks.length,'Projects explicitly marked at risk by their owners.','Projects'],['Pending reviews',pending.length,'Submitted purchase requests awaiting an independent decision.','Procurement']].map(a=>`<section class="card module"><span class="spark">✧</span><h3>${a[0]}</h3><div class="stat-number">${a[1]}</div><p>${a[2]}</p>${button('Open records →','navigate',a[3])}</section>`).join('')}</div>`+footer();}
async function audit(){const rows=await api('/audit');state.audit=rows;$('#app').innerHTML=heading('Audit trail','Append-only records of changes and decisions.',button('Export audit log','export-audit'))+(rows.length?table(['TIME','ACTOR','ACTION','RECORD','DETAILS'],rows.map(r=>`<tr>${cell(dt(r.created_at))}${cell(escape(r.actor_name))}${cell(escape(r.action.replaceAll('_',' ')))}${cell(escape(r.record_type)+' · '+r.record_id.slice(0,8))}${cell(escape(r.details))}</tr>`)):empty('No changes recorded','Workspace activity will appear here.'))+`<p class="page-note">Showing the latest 500 events. Database triggers prevent updates and deletes through normal SQL. A database administrator with filesystem access remains a trusted operator.</p>`+footer();}
async function settings(){
  const [workspaces,units,provider]=await Promise.all([api('/workspaces'),api('/organization-units'),api('/assistant/status')]);
  $('#app').innerHTML=heading('Workspace settings','Organization identity, policy and operating details.')+`<section class="card block"><div class="settings-row"><h3>${escape(state.me.organization.name)}</h3><p>${escape(state.me.organization.industry)} · ${escape(state.me.organization.currency)}<br>Signed in as ${escape(state.me.user.name)} · ${escape(state.me.user.email)} · ${escape(state.me.user.role)}</p>${workspaces.length>1?`<div class="flex"><select class="select-small" id="workspaceSelect">${workspaces.map(w=>`<option value="${w.id}" ${w.id===state.me.organization.id?'selected':''}>${escape(w.name)} · ${w.role}</option>`).join('')}</select>${button('Switch workspace','switch-workspace')}</div>`:''}</div>${isRole('admin')&&!state.me.organization.is_demo?`<div class="settings-row"><h3 class="inline-title">Explore connected sample workflows</h3><p>Open a separate Meridian Group workspace with sample records. Your organization’s existing records remain separate.</p>${button('Open seeded workspace','seed-workspace')}</div>`:''}<div class="settings-row"><h3 class="inline-title">Branches & departments</h3>${units.map(u=>`<p>${escape(u.name)} · ${escape(u.kind)} · ${escape(u.location)}</p>`).join('')||'<p>No organizational units yet.</p>'}${isRole('admin')?button('＋ Add unit','new-unit'):''}</div><div class="settings-row"><h3 class="inline-title">Message retention and edits</h3><p>Authors may edit or remove a message for ${state.me.organization.message_edit_minutes} minutes. Original content is preserved in server history. Removed messages become tombstones; attachment downloads through the message are blocked.</p></div><div class="settings-row"><h3 class="inline-title">AI connection</h3><p>${provider.configured?`Connected to ${escape(provider.destination)} · ${escape(provider.model)}. Conversation data is sent only when a user requests assistance.`:'No generative AI provider is configured. Workspace signals and reviewed text extraction remain available.'}</p></div><div class="settings-row"><h3 class="inline-title">Operating scope</h3><p>Business records persist in this server’s SQLite database. Back up the database regularly. Industry-specific clinical, banking and statutory accounting requirements require separately validated extensions. Finance supports a single workspace currency and tax-exclusive invoicing.</p></div><div class="actions">${button('Export accessible records','export-workspace')}${button('Sign out','logout')}</div></section>`+footer();
}
async function updateNotifications(){if(!state.me)return;const ns=await api('/notifications');state.notifications=ns;const n=ns.filter(n=>!n.read_at).length;$('#notificationCount').className=n?'notification-dot':'';$('#notificationCount').textContent=n||'';}
async function assets(){const rows=await api('/assets');state.assets=rows;$('#app').innerHTML=heading('Assets','Track ownership, assignment and condition.',isRole('admin','manager')?button('＋ Register asset','new-asset','',true):'')+(rows.length?table(['ASSET','TAG','CATEGORY','ASSIGNEE','PROJECT','VALUE','STATUS'],rows.map(a=>`<tr>${cell(escape(a.name)+`<span class="subtext">${button('Discuss asset','record-chat','asset:'+a.id)}</span>`)}${cell(escape(a.tag))}${cell(escape(a.category))}${cell(escape(a.assignee_name||'Unassigned'))}${cell(escape(a.project_name||'Workspace'))}${cell(currency(a.purchase_value))}${cell(isRole('admin','manager')?`<select class="select-small" data-change="asset-status" data-id="${a.id}">${['available','assigned','maintenance','retired'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select>`:badge(a.status))}</tr>`)):empty('Register your business assets','Keep equipment, vehicles and devices linked to people and projects.',isRole('admin','manager')?'new-asset':''))+footer();}
function newAsset(){modal('Register an asset',`<div class="form-grid">${field('name','Asset name','text','',{full:true,maxlength:160})}${field('tag','Unique asset tag','text','',{maxlength:80})}${field('category','Category','text','',{maxlength:80})}${select('assignee_id','Assignee',[['','Unassigned'],...peopleOptions()])}${select('project_id','Project',projectOptions())}${field('purchase_value',`Purchase value (${state.me.organization.currency})`,'number','0',{min:0,step:'0.01'})}${area('notes','Notes')}</div>`,'asset','Register asset');}
async function contracts(){const rows=await api('/contracts');state.contracts=rows;$('#app').innerHTML=heading('Contracts','Track business commitments and their dates.',button('＋ Add contract','new-contract','',true))+(rows.length?table(['CONTRACT','COUNTERPARTY','TYPE','VALUE','END DATE','STATUS'],rows.map(c=>`<tr>${cell(escape(c.title)+`<span class="subtext">${button('Discuss contract','record-chat','contract:'+c.id)}</span>`)}${cell(escape(c.counterparty))}${cell(escape(c.kind))}${cell(currency(c.value))}${cell(escape(c.ends_on||'Open-ended'))}${cell(`<select class="select-small" data-change="contract-status" data-id="${c.id}">${['draft','active','closed'].map(s=>`<option ${s===c.status?'selected':''}>${s}</option>`).join('')}</select>`)}</tr>`)):empty('Keep your commitments visible','Record contract metadata and terms. Status changes track internal review; Nexus does not sign or accept agreements.','new-contract'))+footer();}
function newContract(){modal('Record a contract',`<div class="form-grid">${field('title','Contract title','text','',{full:true,maxlength:200})}${field('counterparty','Counterparty','text','',{maxlength:200})}${select('kind','Contract type',['customer','supplier','employment','other'].map(s=>[s,s]))}${field('value',`Value (${state.me.organization.currency})`,'number','0',{min:0,step:'0.01'})}${select('project_id','Project',projectOptions())}${field('starts_on','Start date','date')}${field('ends_on','End date','date','',{required:false})}${area('notes','Terms / notes')}</div><p class="hint">This records contract metadata. It does not execute an agreement or provide electronic signatures.</p>`,'contract','Save contract');}
async function industry(){
  state.packages=await api('/packages');const id=state.tab||'';const p=state.packages.find(p=>p.id===id);
  let content;
  if(p?.enabled){
    const rows=await api(`/packages/${p.id}/records`);state.packageRecords=rows;
    content=`<div class="flex spacer-top"><h2 class="grow inline-title">${escape(p.name)}</h2>${canWrite()?button('＋ Add '+escape(p.record_name),'new-extension',p.id,true):''}</div><p class="hint">${escape(p.description)}</p>`+(rows.length?table(['PROJECT',...p.fields.map(f=>escape(f.label).toUpperCase()),'AUTHOR'],rows.map(r=>`<tr>${cell(escape(r.project_name))}${p.fields.map(f=>cell(f.type==='money'?currency(r.payload[f.key]):escape(r.payload[f.key]??''))).join('')}${cell(escape(r.author_name))}</tr>`)):empty('No '+p.record_name.toLowerCase()+'s yet','Create an entry against a project you may access.','new-extension-record'));
  }else content=`<div class="record-grid">${state.packages.map(p=>`<article class="card record-card"><span class="avatar purple">⊞</span><h3>${escape(p.name)}</h3><p>${escape(p.description)}</p><span class="hint">Extension contract v${p.contract_version} · ${p.enabled?'Active':'Available'}</span><div class="actions">${p.enabled?button('Open records','tab',p.id):isRole('admin')?button('Activate package','activate-package',p.id,true):'<span class="hint">Ask an administrator to activate.</span>'}</div></article>`).join('')}</div>`;
  $('#app').innerHTML=heading('Industry apps','Isolated applications built on your organization’s universal core.',p?button('All packages','tab',''):'' )+`<div class="notice">Available packages add project costing and time recording. Regulated clinical, banking, insurance and other specialist processes are not supplied or represented as compliant by these packages.</div>`+content+footer();
}
function newExtension(id){const p=state.packages.find(p=>p.id===id);if(!state.projects.length)throw new Error('Create a project before recording an industry entry.');state.activePackage=p;modal('Add '+p.record_name.toLowerCase(),`<div class="form-grid">${select('project_id','Project',state.projects.map(p=>[p.id,p.name]))}${p.fields.map(f=>f.type==='enum'?select(f.key,f.label,f.options.map(o=>[o,o])):field(f.key,f.label,f.type==='money'||f.type==='integer'?'number':f.type==='date'?'date':'text','',{required:f.required!==false,min:f.type==='integer'?1:f.type==='money'?0:undefined,step:f.type==='money'?'0.01':f.type==='integer'?'1':undefined})).join('')}</div>`,'extension','Save entry');}
async function assistant(){
  if(!state.conversation)throw new Error('Choose a conversation first.');
  const config=await api('/assistant/status');
  if(!config.configured){modal('Connect an AI provider','<p class="hint">No generative AI provider is connected. Ask your administrator to configure a local or hosted model. Your existing conversations, business intelligence and reviewed message-to-action extraction work without it.</p>');return;}
  modal('Conversation assistant',`<div class="notice">This sends the latest 100 accessible messages in <b>${escape(state.conversation.name)}</b> to <b>${escape(config.destination)}</b> using model ${escape(config.model)}. Attachments and other conversations are excluded. The answer is a draft and cannot execute business actions.</div><div class="form-grid">${select('action','Assistance',[['summary','Summarize discussion'],['actions','Extract action items'],['reply','Draft a reply'],['translate','Translate latest message']])}${field('language','Translation language (if needed)','text','',{required:false,maxlength:50})}</div>`,'assistant','Send to configured provider');
}
function newUnit(){modal('Add an organization unit',`<div class="form-grid">${field('name','Name','text','',{maxlength:160})}${select('kind','Unit type',[['department','Department'],['branch','Branch']])}${field('location','Location','text','',{required:false,full:true,maxlength:500})}</div>`,'unit','Create unit');}
async function notifications(){await updateNotifications();modal('Notifications',`<div class="notifications-list">${state.notifications.length?state.notifications.map(n=>`<div class="notification-item">${!n.read_at?'● ':''}${escape(n.text)}<span class="subtext">${dt(n.created_at)}</span></div>`).join(''):'<div class="empty">You’re all caught up.</div>'}</div>`);await api('/notifications/read','POST');await updateNotifications();}
function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function searchWorkspace(q){
  const exact=navs.find(n=>n[1].toLowerCase().includes(q.toLowerCase()));if(exact){await navigate(exact[1]);return;}
  const [ps,customers,docs,ts]=await Promise.all([api('/projects'),api('/customers'),api('/documents'),api('/tasks')]);
  const hit=s=>String(s).toLowerCase().includes(q.toLowerCase());
  state.projects=ps;state.documents=docs;
  const items=[...ps.filter(p=>hit(p.name+' '+p.description)).map(p=>[p.name,'Project','project-detail',p.id]),...customers.filter(c=>hit(c.name+' '+c.company+' '+c.notes)).map(c=>[c.name,'Customer','navigate','Customers']),...docs.filter(d=>hit(d.title+' '+d.body)).map(d=>[d.title,'Document','doc-detail',d.id]),...ts.filter(t=>hit(t.title+' '+t.description)).map(t=>[t.title,'Task','navigate','Tasks'])];
  modal('Search results',items.length?`<p class="hint">Records you may access matching “${escape(q)}”</p>${items.map(i=>`<div class="approval"><div class="grow"><strong>${escape(i[0])}</strong><small>${i[1]}</small></div>${button('Open',i[2],i[3])}</div>`).join('')}`:'<div class="empty">No matching accessible records.</div>');
}

document.addEventListener('click',async event=>{
  const b=event.target.closest('[data-action]');if(!b||b.disabled)return;
  const action=b.dataset.action,id=b.dataset.id;
  try{
    if(action==='auth-mode'){showAuth(id);return;}
    if(action==='close-modal'){closeModal();return;}
    if(action==='navigate'){closeModal();await navigate(id);return;}
    if(action==='settings'){closeModal();await navigate('Settings');return;}
    if(action==='logout'){await api('/auth/logout','POST');state.me=null;state.csrf='';stopPolling();closeModal();showAuth('login');return;}
    if(action==='notifications'){await notifications();return;}
    if(action==='assistant'){await assistant();return;}
    if(action==='new-asset'){newAsset();return;}
    if(action==='new-contract'){newContract();return;}
    if(action==='new-unit'){newUnit();return;}
    if(action==='activate-package'){await api(`/packages/${id}/activate`,'POST');state.tab=id;await industry();toast('Industry package activated.');return;}
    if(action==='new-extension'||action==='new-extension-record'){newExtension(id||state.tab);return;}
    if(action==='switch-workspace'){const org_id=$('#workspaceSelect').value;await api('/auth/switch','POST',{org_id});state.conversation=null;await enter();return;}
    if(action==='new-project'){newProject();return;}
    if(action==='project-detail'){await projectDetail(id);return;}
    if(action==='project-chat'){const cs=await api('/conversations');state.conversation=cs.find(c=>c.project_id===id);closeModal();await navigate('Nexus Connect');return;}
    if(action==='project-task'){newTask(null,id);return;}
    if(action==='add-project-member'){const user_id=$('#addProjectMember').value;if(!user_id)throw new Error('All active members already have access.');await api(`/projects/${id}/members`,'POST',{user_id});await projectDetail(id);toast('Project access granted.');return;}
    if(action==='remove-project-member'){await api(`/projects/${state.editProject.id}/members`,'POST',{user_id:id,remove:true});await projectDetail(state.editProject.id);toast('Project access revoked.');return;}
    if(action==='new-task'){newTask();return;}
    if(action==='new-conversation'){newConversation();return;}
    if(action==='record-chat'){
      const [record_kind,record_id]=id.split(':');const c=await api('/record-conversations','POST',{record_kind,record_id});state.conversation=c;closeModal();await navigate('Nexus Connect');return;
    }
    if(action==='open-context'){
      const [kind,recordId]=id.split(':');const pages={customer:'Customers',supplier:'Operations',invoice:'Finance',requisition:'Procurement',task:'Tasks',asset:'Assets',contract:'Contracts',document:'Documents',meeting:'Meetings',purchase_order:'Operations'};
      closeModal();await navigate(pages[kind]);if(kind==='requisition')await reqDetail(recordId);if(kind==='document')await docDetail(recordId);if(kind==='meeting')meetingDetail(recordId);return;
    }
    if(action==='select-channel'){state.conversation=state.conversations.find(c=>c.id===id);state.reply=null;state.aroundMessage=null;state.messageSignature='';await connect();return;}
    if(action==='reply'){const m=state.messages.find(m=>m.id===id);state.reply=m;$('#replyContext').innerHTML=`Replying to ${escape(m.author_name)}: ${escape(m.body.slice(0,100))} <button class="text-button" data-action="cancel-reply">Cancel</button>`;$('#replyContext').hidden=false;$('#messageBody').focus();return;}
    if(action==='cancel-reply'){state.reply=null;$('#replyContext').hidden=true;return;}
    if(action==='react'){await api(`/messages/${id}/react`,'POST',{emoji:b.dataset.emoji||'👍'});await loadMessages();return;}
    if(action==='pin-message'){const m=state.messages.find(m=>m.id===id);await api('/messages/'+id,'PATCH',{pinned:!m.pinned});await loadMessages();return;}
    if(action==='edit-message'){const m=state.messages.find(m=>m.id===id);state.editMessage=id;modal('Edit message',`<div class="form-grid">${area('body','Message',m.body,true)}</div><p class="hint">Original content remains in server history. Editing is allowed within the organization’s editing window.</p>`,'edit-message','Save edit');return;}
    if(action==='remove-message'){state.editMessage=id;modal('Remove message',`<p class="hint">This replaces the visible message with a removal notice and blocks attachment downloads. The original remains in server history.</p>`,'remove-message','Remove message');return;}
    if(action==='message-task'){const m=state.messages.find(m=>m.id===id);newTask({...m,project_id:state.conversation.project_id||state.conversation.context_project_id});return;}
    if(action==='message-req'){const draft=await api('/extract','POST',{message_id:id});newReq(draft);return;}
    if(action==='source-message'){closeModal();await sourceMessage(id);return;}
    if(action==='new-customer'){newCustomer();return;}
    if(action==='tab'){state.tab=id;await render();return;}
    if(action==='new-product'){newProduct();return;}
    if(action==='new-supplier'){newSupplier();return;}
    if(action==='stock'){stock(id);return;}
    if(action==='new-req'){newReq();return;}
    if(action==='req-detail'){await reqDetail(id);return;}
    if(action==='edit-req'){state.editReq=state.activeReq;state.reqSource=null;modal('Edit requisition draft',reqForm(state.editReq),'requisition','Save draft');return;}
    if(action==='submit-req'){await api(`/requisitions/${id}/submit`,'POST');await reqDetail(id);if(state.page==='Procurement')await procurement();toast('Submitted for independent review.');return;}
    if(action==='review-approve'||action==='review-reject'){await reviewReq(id,action==='review-approve'?'approved':'rejected');return;}
    if(action==='issue-order'){await orderForm(id);return;}
    if(action==='new-invoice'){await newInvoice();return;}
    if(action.startsWith('invoice-')){await invoiceAction(id,action.slice(8));return;}
    if(action==='new-doc'){newDoc();return;}
    if(action==='doc-detail'){await docDetail(id);return;}
    if(action==='edit-doc'){newDoc(state.documents.find(d=>d.id===id));return;}
    if(action==='new-meeting'){newMeeting();return;}
    if(action==='meeting-detail'){meetingDetail(id);return;}
    if(action==='invite'){invite();return;}
    if(action==='edit-role'){editRole(id);return;}
    if(action==='copy-invite'){await navigator.clipboard.writeText($('#f-invitationLink').value);toast('Invitation copied. Share it privately with the invited teammate.');return;}
    if(action==='export-ledger'){download('nexus-ledger.json',state.ledger);return;}
    if(action==='export-audit'){download('nexus-audit.json',state.audit);return;}
    if(action==='export-workspace'){const endpoints=['projects','tasks','customers','products','suppliers','requisitions','documents','meetings','assets','organization-units'];if(isRole('admin','finance'))endpoints.push('invoices','ledger');const values=await Promise.all(endpoints.map(e=>api('/'+e)));download('nexus-workspace.json',Object.fromEntries(endpoints.map((e,i)=>[e,values[i]])));toast('Accessible records exported. Messages and attachments are excluded.');return;}
  }catch(e){toast(e.message);}
});

document.addEventListener('submit',async event=>{
  const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();
  const d=Object.fromEntries(new FormData(form)),kind=form.dataset.form,submit=form.querySelector('button[type=submit]');
  if(submit)submit.disabled=true;const error=form.querySelector('.form-error');if(error)error.textContent='';
  try{
    if(kind==='auth'){const result=await api('/auth/'+form.dataset.mode,'POST',d);state.csrf=result.csrf;await enter();return;}
    if(kind==='asset'){await api('/assets','POST',d);closeModal();await assets();return;}
    if(kind==='contract'){await api('/contracts','POST',d);closeModal();await contracts();return;}
    if(kind==='unit'){await api('/organization-units','POST',d);closeModal();await settings();return;}
    if(kind==='extension'){for(const f of state.activePackage.fields)if(f.type==='integer')d[f.key]=Number(d[f.key]);await api(`/packages/${state.activePackage.id}/records`,'POST',d);closeModal();await industry();return;}
    if(kind==='assistant'){d.conversation_id=state.conversation.id;const result=await api('/assistant','POST',d);modal('Assistant draft',`<div class="notice">Generated by ${escape(result.provider)}. Verify claims and cited message IDs before using this output. No business action was executed.</div><div class="preformatted">${escape(result.text)}</div>`, '', '',true);return;}
    if(kind==='project'){d.private=!!form.querySelector('[name=private]').checked;await api('/projects','POST',d);await refreshReference();closeModal();await navigate('Projects');toast('Project and conversation created.');return;}
    if(kind==='task'){d.source_message_id=state.taskSource?.id||null;await api('/tasks','POST',d);closeModal();if(state.page==='Tasks')await tasks();else if(state.page==='Overview')await overview();toast('Task created and saved.');return;}
    if(kind==='conversation'){d.members=d.kind==='direct'?[d.member_id]:[];state.conversation=await api('/conversations','POST',d);closeModal();await connect();return;}
    if(kind==='message'){
      d.parent_id=state.reply?.id||null;const c=state.conversation.id;
      const m=await api(`/conversations/${c}/messages`,'POST',d);form.reset();state.reply=null;$('#replyContext').hidden=true;
      const file=$('#messageFile').files[0];
      if(file){
        if(file.size>5*1024*1024){toast('Message saved. Attachment exceeds 5 MB and was not uploaded.');}
        else{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Unable to read file'));reader.readAsDataURL(file);});try{await api(`/messages/${m.id}/attachments`,'POST',{filename:file.name,mime:['application/pdf','image/png','image/jpeg','text/plain','text/csv'].includes(file.type)?file.type:'application/octet-stream',content});}catch(e){toast('Message saved; attachment failed: '+e.message);}}
        $('#messageFile').value='';
      }
      state.aroundMessage=null;await loadMessages(true);return;
    }
    if(kind==='edit-message'){await api('/messages/'+state.editMessage,'PATCH',d);closeModal();await loadMessages();return;}
    if(kind==='remove-message'){await api('/messages/'+state.editMessage,'PATCH',{deleted:true});closeModal();await loadMessages();return;}
    if(kind==='customer'){await api('/customers','POST',d);closeModal();await customers();return;}
    if(kind==='supplier'){await api('/suppliers','POST',d);closeModal();await operations();return;}
    if(kind==='product'){await api('/products','POST',d);closeModal();await operations();return;}
    if(kind==='stock'){d.quantity=Number(d.quantity);await api(`/products/${state.stockProduct}/stock`,'POST',d);closeModal();await operations();toast('Stock movement recorded.');return;}
    if(kind==='requisition'){d.quantity=Number(d.quantity);d.source_message_id=state.reqSource?.source_message_id||null;if(state.editReq)await api('/requisitions/'+state.editReq.id,'PATCH',d);else await api('/requisitions','POST',d);closeModal();if(state.page==='Procurement')await procurement();toast('Requisition draft saved. Submit it from Procurement when ready.');return;}
    if(kind==='review'){const {id,decision}=state.review;await api(`/requisitions/${id}/review`,'POST',{decision,comment:d.comment});closeModal();await render();toast('Decision recorded in the audit trail.');return;}
    if(kind==='order'){await api(`/requisitions/${state.orderReq}/order`,'POST',d);closeModal();await render();toast('Purchase order recorded.');return;}
    if(kind==='invoice'){await api('/invoices','POST',d);closeModal();await finance();return;}
    if(kind==='invoice-action'){const {id,action}=state.invoiceAction;await api(`/invoices/${id}/${action}`,'POST');closeModal();await finance();toast('Invoice updated; balanced journal entry posted.');return;}
    if(kind==='document'){if(state.editDoc)await api('/documents/'+state.editDoc.id,'PATCH',d);else await api('/documents','POST',d);closeModal();await knowledge();return;}
    if(kind==='meeting'){d.starts_at=new Date(d.starts_at).toISOString();d.ends_at=new Date(d.ends_at).toISOString();d.attendees=new FormData(form).getAll('attendees');await api('/meetings','POST',d);closeModal();await meetings();toast('Meeting saved and workspace invitations delivered.');return;}
    if(kind==='invite'){
      const r=await api('/invitations','POST',d),link=location.origin+'/#invite='+r.token;
      modal('Invitation created',`<p class="hint">Share this link privately with <b>${escape(r.email)}</b>. It expires in 24 hours and can be accepted once. No email has been sent.</p><div class="form-grid">${field('invitationLink','Invitation link','text',link,{full:true})}</div><div class="actions spacer-top">${button('Copy invitation','copy-invite')}</div>`);
      return;
    }
    if(kind==='role'){await api('/people/'+state.editPerson.id,'PATCH',d);closeModal();await enter();await navigate('People');toast('Workspace role updated.');return;}
  }catch(e){if(error&&form.isConnected)error.textContent=e.message;else toast(e.message);}
  finally{if(submit)submit.disabled=false;}
});
document.addEventListener('change',async e=>{
  const el=e.target;if(!el.dataset.change)return;const action=el.dataset.change,id=el.dataset.id;
  try{
    if(action==='task-status')await api('/tasks/'+id,'PATCH',{status:el.value});
    if(action==='project-status'){await api('/projects/'+id,'PATCH',{status:el.value});await refreshReference();}
    if(action==='customer-stage')await api('/customers/'+id,'PATCH',{stage:el.value});
    if(action==='rsvp')await api(`/meetings/${id}/rsvp`,'POST',{rsvp:el.value});
    if(action==='asset-status')await api('/assets/'+id,'PATCH',{status:el.value});
    if(action==='contract-status')await api('/contracts/'+id,'PATCH',{status:el.value});
    refreshManagedTable(el);toast('Change saved.');
  }catch(error){toast(error.message);await render();}
});
document.addEventListener('input',e=>{if(e.target.id==='chatSearch'){clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>loadMessages().catch(e=>toast(e.message)),350);}});
document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#globalSearch')?.focus();}
  if(e.target.id==='globalSearch'&&e.key==='Enter'&&e.target.value.trim())searchWorkspace(e.target.value.trim()).catch(e=>toast(e.message));
  if(e.target.id==='messageBody'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form.requestSubmit();}
});
$('#modal').addEventListener('cancel',e=>{if(state.uploading)e.preventDefault();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
async function boot(){const invite=location.hash.match(/^#invite=(.+)$/);if(invite){history.replaceState(null,'',location.pathname);showAuth('join',decodeURIComponent(invite[1]));return;}try{await enter();}catch(e){showAuth('login');if(!e.message.includes('Sign in'))toast(e.message);}}
boot();
